<?php
require_once __DIR__ . '/../includes/init.php'; requireAdmin();
$pdo=db();
$stats=[
 ['Total items',(int)$pdo->query('SELECT COUNT(*) FROM items')->fetchColumn(),'▤','green'],
 ['Total stock',(int)$pdo->query('SELECT COALESCE(SUM(quantity),0) FROM items')->fetchColumn(),'▦','blue'],
 ['Low stock',(int)$pdo->query('SELECT COUNT(*) FROM items WHERE quantity<=reorder_level')->fetchColumn(),'⚑','amber'],
 ['Stock in today',(int)$pdo->query("SELECT COALESCE(SUM(quantity),0) FROM stock_movements WHERE movement_type='IN' AND movement_date=CURDATE()")->fetchColumn(),'↙','green'],
 ['Stock out today',(int)$pdo->query("SELECT COALESCE(SUM(quantity),0) FROM stock_movements WHERE movement_type='OUT' AND movement_date=CURDATE()")->fetchColumn(),'↗','red'],
];
$low=$pdo->query('SELECT item_code,item_name,category,quantity,unit,reorder_level FROM items WHERE quantity<=reorder_level ORDER BY quantity ASC LIMIT 8')->fetchAll();
$recent=historyRows([],6); $title='Dashboard'; $active='dashboard'; layoutStart($title,$active);
?><div class="page-heading"><div><div class="eyebrow">OVERVIEW</div><h1>Good <?= (int)date('G')<12?'morning':((int)date('G')<18?'afternoon':'evening') ?>, <?= e(explode(' ',currentUser()['full_name'])[0]) ?></h1><p>Here’s what’s happening in your warehouse today.</p></div><a class="button primary" href="<?= e(url('admin/movements.php')) ?>">＋ Record movement</a></div>
<section class="stats-grid five"><?php foreach($stats as [$label,$value,$icon,$color]): ?><article class="stat-card"><span class="stat-icon <?= e($color) ?>"><?= e($icon) ?></span><span class="stat-label"><?= e($label) ?></span><strong><?= number_format($value) ?></strong><span class="stat-note">Live inventory data</span></article><?php endforeach; ?></section>
<div class="content-grid"><section class="panel"><div class="panel-heading"><div><h2>Low stock items</h2><p>Items at or below their reorder level</p></div><a class="text-link" href="<?= e(url('admin/items.php')) ?>">View inventory →</a></div><div class="table-wrap"><table><thead><tr><th>Item</th><th>Category</th><th>Quantity</th><th>Reorder level</th></tr></thead><tbody><?php if (!$low): ?><tr><td colspan="4" class="empty">No low-stock items right now.</td></tr><?php else: foreach($low as $r): ?><tr><td><b><?= e($r['item_name']) ?></b><small class="subtext"><?= e($r['item_code']) ?></small></td><td><?= e($r['category']) ?></td><td><span class="badge warning"><?= e($r['quantity'].' '.$r['unit']) ?></span></td><td><?= e($r['reorder_level']) ?></td></tr><?php endforeach; endif; ?></tbody></table></div></section>
<section class="panel"><div class="panel-heading"><div><h2>Recent movements</h2><p>Latest inventory activity</p></div><a class="text-link" href="<?= e(url('admin/movements.php')) ?>">See all →</a></div><div class="activity-list"><?php if(!$recent): ?><p class="empty">No stock movements yet.</p><?php else: foreach($recent as $r): ?><div class="activity-row"><span class="movement-dot <?= strtolower($r['movement_type']) ?>"><?= $r['movement_type']==='IN'?'↓':'↑' ?></span><div><b><?= e($r['item_name']) ?></b><small><?= e($r['item_code']) ?> · <?= e(dateValue($r['movement_date'])) ?></small></div><strong class="<?= strtolower($r['movement_type']) ?>-text"><?= $r['movement_type']==='IN'?'+':'−' ?><?= e($r['quantity']) ?></strong></div><?php endforeach; endif; ?></div></section></div><?php layoutEnd(); ?>
